SELECT p.name
FROM patients p
WHERE p.patient_id NOT IN (SELECT patient_id FROM appointments);

SELECT d.full_name, d.consultation_fee
FROM doctors d
WHERE d.consultation_fee > (
    SELECT AVG(consultation_fee) 
    FROM doctors
);

UPDATE medicines
SET unit_price = unit_price * 1.20
WHERE unit_price < 10;
